<?php declare(strict_types=1);require dirname(__DIR__).'/_inc/action-bootstrap.php';$token=(string)(($_SERVER['REQUEST_METHOD']??'')==='POST'?($_POST['t']??''):($_GET['t']??''));$db=Database::platform();$service=$db?new SavedNumbersService($db):null;$row=$service?$service->findConfirm($token):null;$done=null;if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&validPost()&&$row){$done=$service->confirm($token);if($done){try{(new ToolUsageCounter($db))->increment($done['tool'],'saves_confirmed');}catch(Throwable $e){}}}toolsStart('Confirm saved numbers | Ittai','Confirm your saved calculator numbers.','https://ittai.ca/tools/confirm/','Confirm saved numbers');?><header class="hero"><h1><?= $done?'Saved':'Confirm and save'?></h1></header><?php if($done):?><p>Your numbers are saved.</p><p><a href="/tools/delete/?t=<?=h($done['delete_token'])?>">Delete my saved numbers</a></p><?php elseif($row&&$row['status']==='pending'):?><p><?=h($row['tool'])?>: <?=h($row['inputs_json'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['tool_csrf'])?>"><input type="hidden" name="t" value="<?=h($token)?>"><button type="submit">Confirm and save</button></form><?php else:?><p>This link is invalid or has expired.</p><?php endif;toolsEnd();
